+#include "config.h"
+
+#include <stdlib.h>
+#include <string.h>
+#include <errno.h>
+
+#include <wsutil/pint.h>
+
+#include "wtap-int.h"
+#include "file_wrappers.h"
+#include "required_file_handlers.h"
+#include "pcap-common.h"
+#include "pcap-encap.h"
+#include "libpcap.h"
+#include "arkime.h"
+
+/*
+ * These are copied from libpcap.c
+ */
+#define LT_LINKTYPE(x)              ((x) & 0x0000FFFF)
+#define LT_RESERVED1(x)             ((x) & 0x03FF0000)
+#define LT_FCS_LENGTH_PRESENT(x)    ((x) & 0x04000000)
+#define LT_FCS_LENGTH(x)            (((x) & 0xF0000000) >> 28)
+
+#define ARK_VER_MAJ 2
+#define ARK_VER_MIN 4
+
+#define ARK_REC_HDR_LEN 6
+
+/*
+ * Private file type/subtype value
+ */
+static int arkime_file_type_subtype = -1;
+
+/*
+ * Private per-wtap_t data needed to read a file
+ */
+typedef struct {
+    gboolean byte_swapped;      /* Whether file is opposite endianness to us */
+    int fcs_len;                /* Length of Frame Check Sequence */
+    gint32 start_secs;          /* 1 minute earlier than the second in which the first packet was written */
+} arkime_priv_t;
+
+/*
+ * Private per-wtap_dumper_t data needed when writing a file
+ */
+typedef struct {
+    gboolean wrote_header;
+    gint32 start_secs;
+} arkime_dump_priv_t;
+
+/*
+ * Read a single packet. Called from arkime_read() and arkime_seek_read()
+ */
+static gboolean
+arkime_read_packet(wtap *wth, FILE_T fh, wtap_rec *rec,
+    Buffer *buf, int *err, gchar **err_info)
+{
+    guint16 packet_size;
+    guint32 packet_time;
+    arkime_priv_t *priv = (arkime_priv_t *)wth->priv;
+    guint8 header[ARK_REC_HDR_LEN];
+
+    if (!wtap_read_bytes_or_eof(fh, &header, ARK_REC_HDR_LEN, err, err_info))
+        return FALSE;
+
+    /* arkime writes these fields using memcpy, we'll read them the same way */
+    memcpy(&packet_size, header, 2);
+    memcpy(&packet_time, header + 2, 4);
+    if (priv->byte_swapped) {
+        packet_size = GUINT16_SWAP_LE_BE(packet_size);
+        packet_time = GUINT32_SWAP_LE_BE(packet_time);
+    }
+
+    /* is this test from libpcap.c even possible in arkime format
+     * which only has a 16-bit length field? */
+    if (packet_size > wtap_max_snaplen_for_encap(wth->file_encap)) {
+        /*
+         * Probably a corrupt capture file; return an error,
+         * so that our caller doesn't blow up trying to allocate
+         * space for an immensely-large packet.
+         */
+        *err = WTAP_ERR_BAD_FILE;
+        if (err_info != NULL) {
+            *err_info = ws_strdup_printf("arkime: File has %u-byte packet, bigger than maximum of %u",
+                                         packet_size,
+                                         wtap_max_snaplen_for_encap(wth->file_encap));
+        }
+        return FALSE;
+    }
+
+    rec->rec_type = REC_TYPE_PACKET;
+    rec->block = wtap_block_create(WTAP_BLOCK_PACKET);
+    rec->rec_header.packet_header.caplen = packet_size;
+    rec->rec_header.packet_header.len = packet_size;
+    rec->presence_flags = WTAP_HAS_TS;
+    rec->ts.secs = priv->start_secs + ((packet_time >> 20) & 0x0FFF);
+    rec->ts.nsecs = (packet_time & 0x000FFFFF) * 1000;
+
+    /*
+     * Read the packet data.
+     */
+    if (!wtap_read_packet_bytes(fh, buf, packet_size, err, err_info))
+        return FALSE;
+
+    pcap_read_post_process(FALSE, wth->file_encap, rec,
+                           ws_buffer_start_ptr(buf), priv->byte_swapped, priv->fcs_len);
+    return TRUE;
+}
+
+/*
+ * Read the next packet in order
+ */
+static gboolean
+arkime_read(wtap *wth, wtap_rec *rec, Buffer *buf,
+    int *err, gchar **err_info, gint64 *data_offset)
+{
+    *data_offset = file_tell(wth->fh);
+    return arkime_read_packet(wth, wth->fh, rec, buf, err, err_info);
+}
+
+/*
+ * Read packet at requested offset
+ */
+static gboolean
+arkime_seek_read(wtap *wth, gint64 seek_off, wtap_rec *rec,
+    Buffer *buf, int *err, gchar **err_info)
+{
+    if (file_seek(wth->random_fh, seek_off, SEEK_SET, err) == -1)
+        return FALSE;
+
+    if (!arkime_read_packet(wth, wth->random_fh, rec, buf, err,
+            err_info)) {
+        if (*err == 0)
+            *err = WTAP_ERR_SHORT_READ;
+        return FALSE;
+    }
+    return TRUE;
+}
+
+/*
+ * Open a file and see if it's in arkime format
+ */
+wtap_open_return_val
+arkime_open(wtap *wth, int *err, gchar **err_info)
+{
+    guint32 magic;
+    struct pcap_hdr hdr;
+    gboolean byte_swapped;
+    arkime_priv_t *priv = NULL;
+
+    /* Read in the number that should be at the start of a arkime file */
+    if (!wtap_read_bytes(wth->fh, &magic, sizeof magic, err, err_info)) {
+        if (*err != WTAP_ERR_SHORT_READ)
+            return WTAP_OPEN_ERROR;
+        return WTAP_OPEN_NOT_MINE;
+    }
+
+    switch (magic) {
+        case ARKIME_MAGIC:
+            byte_swapped = FALSE;
+            break;
+        case ARKIME_SWAPPED_MAGIC:
+            byte_swapped = TRUE;
+            break;
+        default:
+            /* Not Arkime's special flavour. libpcap.c may still handle it. */
+            return WTAP_OPEN_NOT_MINE;
+    }
+
+    /* Read the rest of the header. */
+    if (!wtap_read_bytes(wth->fh, &hdr, sizeof hdr, err, err_info))
+        return WTAP_OPEN_ERROR;
+
+    if (byte_swapped) {
+        /* Byte-swap the header fields */
+        magic = GUINT32_SWAP_LE_BE(magic);
+        hdr.version_major = GUINT16_SWAP_LE_BE(hdr.version_major);
+        hdr.version_minor = GUINT16_SWAP_LE_BE(hdr.version_minor);
+        hdr.thiszone = GUINT32_SWAP_LE_BE(hdr.thiszone);
+        hdr.snaplen = GUINT32_SWAP_LE_BE(hdr.snaplen);
+        hdr.network = GUINT32_SWAP_LE_BE(hdr.network);
+    }
+    if (hdr.version_major != ARK_VER_MAJ || hdr.version_minor != ARK_VER_MIN) {
+        /* This is the only version written by Arkime at present. */
+        *err = WTAP_ERR_UNSUPPORTED;
+        *err_info = ws_strdup_printf("arkime: version %u.%u unsupported",
+                                     hdr.version_major, hdr.version_minor);
+        return WTAP_OPEN_ERROR;
+    }
+
+    /*
+     * Check the main reserved field.
+     */
+    if (LT_RESERVED1(hdr.network) != 0) {
+        *err = WTAP_ERR_UNSUPPORTED;
+        *err_info = ws_strdup_printf("arkime: network type reserved field not zero (0x%08x)",
+                                     LT_RESERVED1(hdr.network));
+        return WTAP_OPEN_ERROR;
+    }
+
+    /*
+     * Map the link-layer type from the "network" field in
+     * the header to a Wiretap encapsulation.
+     */
+    wth->file_encap = wtap_pcap_encap_to_wtap_encap(LT_LINKTYPE(hdr.network));
+    if (wth->file_encap == WTAP_ENCAP_UNKNOWN) {
+        *err = WTAP_ERR_UNSUPPORTED;
+        *err_info = ws_strdup_printf("pcap: network type %u unknown or unsupported",
+                                     hdr.network);
+        return WTAP_OPEN_ERROR;
+    }
+
+    /* This is our file */
+    wth->subtype_read = arkime_read;
+    wth->subtype_seek_read = arkime_seek_read;
+    //wth->subtype_close = arkime_close;
+    wth->snapshot_length = hdr.snaplen;
+    wth->file_type_subtype = arkime_file_type_subtype;
+    wth->file_tsprec = WTAP_TSPREC_USEC;
+
+    priv = g_new0(arkime_priv_t, 1);
+    priv->byte_swapped = byte_swapped;
+    priv->start_secs = hdr.thiszone;    // NOTE: unconventional use of thiszone by arkime
+    wth->priv = (void *)priv;
+
+    /*
+     * Extract the FCS information, if present.
+     */
+    priv->fcs_len = -1;
+    if (LT_FCS_LENGTH_PRESENT(hdr.network)) {
+        /*
+         * We have an FCS length.
+         */
+        priv->fcs_len = LT_FCS_LENGTH(hdr.network) * 16;
+    }
+
+    /*
+     * Add an IDB; we don't know how many interfaces were
+     * involved, so we just say one interface, about which
+     * we only know the link-layer type, snapshot length,
+     * and time stamp resolution.
+     */
+    wtap_add_generated_idb(wth);
+
+    return WTAP_OPEN_MINE;
+}
+
+/*
+ * Tell Wireshark if we can save this encapsulation to our file format
+ */
+static int
+arkime_dump_can_write_encap(int encap)
+{
+    /* Per-packet encapsulations aren't supported. */
+    if (encap == WTAP_ENCAP_PER_PACKET)
+        return WTAP_ERR_ENCAP_PER_PACKET_UNSUPPORTED;
+
+    if (wtap_wtap_encap_to_pcap_encap(encap) == -1)
+        return WTAP_ERR_UNWRITABLE_ENCAP;
+
+    /* Yes, we can write this encapsulation. */
+    return 0;
+}
+
+/*
+ * Write a file header for a new file
+ */
+static gboolean
+arkime_dump_write_file_header(wtap_dumper *wdh, gint32 start_secs, int *err)
+{
+    struct pcap_hdr hdr;
+
+    hdr.version_major = ARK_VER_MAJ;
+    hdr.version_minor = ARK_VER_MIN;
+    hdr.thiszone = start_secs;          // NOTE: unconventional use of thiszone by arkime
+    hdr.sigfigs = 0;
+    hdr.network = wtap_wtap_encap_to_pcap_encap(wdh->file_encap);
+
+    /*
+     * Don't write a snapshot length of 0. This can be tricky since wiretap uses
+     * 0 to indicate unknown snapshot length.
+     * In addition, arkime's packet size field is only 16 bits in size.
+     */
+    hdr.snaplen = MIN(G_MAXUINT16,
+                      (wdh->snaplen != 0)
+                        ? (guint)wdh->snaplen
+                        : wtap_max_snaplen_for_encap(wdh->file_encap));
+
+    return wtap_dump_file_write(wdh, &hdr, sizeof hdr, err);
+}
+
+/*
+ * Write a packet to a file
+ */
+static gboolean
+arkime_dump_packet(wtap_dumper *wdh, const wtap_rec *rec, const guint8 *pd,
+    int *err, gchar **err_info _U_)
+{
+    guint16 packet_size;
+    guint32 packet_time;
+    guint8 header[ARK_REC_HDR_LEN] = {0};
+    arkime_dump_priv_t *priv = (arkime_dump_priv_t *)wdh->priv;
+
+    if (!priv->wrote_header) {
+        priv->start_secs = (gint32)(rec->ts.secs - 60);
+        if (!arkime_dump_write_file_header(wdh, priv->start_secs, err))
+            return FALSE;
+        priv->wrote_header = TRUE;
+    }
+
+    /*
+     * Don't write anything we're not willing to read.
+     * (The cast is to prevent an overflow.)
+     */
+    if ((guint64)rec->rec_header.packet_header.caplen >
+            MIN(G_MAXUINT16, wtap_max_snaplen_for_encap(wdh->file_encap))) {
+        *err = WTAP_ERR_PACKET_TOO_LARGE;
+        return FALSE;
+    }
+
+    packet_size = (guint16)rec->rec_header.packet_header.caplen;
+    memcpy(header, &packet_size, 2);
+
+    packet_time = (guint32)(rec->ts.nsecs / 1000);
+    if (priv->start_secs <= rec->ts.secs) {
+        packet_time |= (guint32)((rec->ts.secs - priv->start_secs) << 20);
+    }
+    else {
+        /*
+         * Packets not in time order! Pretend this one falls near
+         * the start of the capture, and don't add seconds to packet_time.
+         * Behaviour from arkime:
+         * https://github.com/arkime/arkime/blob/1f3a0c61b72b14af1ad02bc9d50ae0d14ff73de5/capture/writer-simple.c#L636
+         */
+    }
+    memcpy(header + 2, &packet_time, 4);
+
+    return wtap_dump_file_write(wdh, header, sizeof header, err) &&
+        wtap_dump_file_write(wdh, pd, packet_size, err);
+}
+
+/*
+ * Open a new dump file for writing.
+ * We need to know the first packet's timestamp before we can write
+ * the header, so we only write the magic bytes here.
+ */
+static gboolean
+arkime_dump_open(wtap_dumper *wdh, int *err, gchar **err_info _U_)
+{
+    const guint32 magic = ARKIME_MAGIC;
+
+    arkime_dump_priv_t *priv = g_new0(arkime_dump_priv_t, 1);
+    wdh->priv = (void *)priv;
+    wdh->subtype_write = arkime_dump_packet;
+
+    return wtap_dump_file_write(wdh, &magic, sizeof magic, err);
+}
+
+/*
+ * Information to register this file type with Wireshark
+ */
+
+static const struct supported_block_type arkime_blocks_supported[] = {
+    /*
+     * We support packet blocks, with no comments or other options.
+     */
+    { WTAP_BLOCK_PACKET, MULTIPLE_BLOCKS_SUPPORTED, NO_OPTIONS_SUPPORTED }
+};
+
+static const struct file_type_subtype_info arkime_info = {
+    "Arkime minimal format", "arkime", "arkime", NULL,
+    FALSE, BLOCKS_SUPPORTED(arkime_blocks_supported),
+    arkime_dump_can_write_encap, arkime_dump_open, NULL
+};
+
+void
+register_arkime(void)
+{
+    arkime_file_type_subtype = wtap_register_file_type_subtype(&arkime_info);
+}

